-- English and French translations for the city destinations and the sample offers.
-- Merged into the existing translations (|| keeps anything already translated by the team).

update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "High-altitude valleys and vineyards, singani and the friendliest climate in Bolivia."}, "fr": {"description": "Vallées et vignobles d''altitude, singani et le climat le plus doux de Bolivie."}}'::jsonb where slug = 'tarija';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "The world''s largest salt flat, colorful lagoons and salt hotels."}, "fr": {"description": "Le plus grand salar du monde, des lagunes colorées et des hôtels de sel."}}'::jsonb where slug = 'uyuni';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "A city in the clouds: cable cars, the Valley of the Moon and the gateway to Titicaca."}, "fr": {"description": "Une ville perchée : téléphériques, la Vallée de la Lune et la porte du Titicaca."}}'::jsonb where slug = 'la-paz';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "Warm weather, nature, Samaipata and the Jesuit missions of Chiquitania."}, "fr": {"description": "Chaleur, nature, Samaipata et les missions jésuites de la Chiquitanía."}}'::jsonb where slug = 'santa-cruz';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "The White City: colonial heritage, museums and dinosaur footprints."}, "fr": {"description": "La Ville blanche : patrimoine colonial, musées et empreintes de dinosaures."}}'::jsonb where slug = 'sucre';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "Mining history, the Cerro Rico and the Royal Mint (Casa de la Moneda)."}, "fr": {"description": "Histoire minière, le Cerro Rico et la Monnaie royale (Casa de la Moneda)."}}'::jsonb where slug = 'potosi';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "Bolivia''s folklore capital and home to one of the biggest carnivals in the Americas."}, "fr": {"description": "Capitale du folklore et l''un des plus grands carnavals des Amériques."}}'::jsonb where slug = 'oruro';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "The country''s food capital and the gateway to Torotoro."}, "fr": {"description": "La capitale gastronomique du pays et la porte de Torotoro."}}'::jsonb where slug = 'cochabamba';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "Panoramic views of La Paz, street markets and cholet architecture."}, "fr": {"description": "Vue panoramique sur La Paz, marchés et architecture cholet."}}'::jsonb where slug = 'el-alto';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "A valley village with El Fuerte, vineyards and Amboró National Park."}, "fr": {"description": "Un village de vallée avec El Fuerte, des vignobles et le parc national Amboró."}}'::jsonb where slug = 'samaipata';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "On the shores of Lake Titicaca and the gateway to Isla del Sol."}, "fr": {"description": "Au bord du lac Titicaca et porte d''entrée de l''Isla del Sol."}}'::jsonb where slug = 'copacabana';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "The Yungas: warm climate, coffee farms and the famous Death Road."}, "fr": {"description": "Les Yungas : climat chaud, plantations de café et la célèbre Route de la Mort."}}'::jsonb where slug = 'coroico';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "The Amazon, the pampas and the entrance to Madidi National Park."}, "fr": {"description": "L''Amazonie, les pampas et l''entrée du parc national Madidi."}}'::jsonb where slug = 'rurrenabaque';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "Canyons, caves and dinosaur footprints."}, "fr": {"description": "Canyons, grottes et empreintes de dinosaures."}}'::jsonb where slug = 'torotoro';
update public.destinations set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"description": "Red landscapes of the south, gorges and the road to the salt flat."}, "fr": {"description": "Les paysages rouges du sud, des gorges et la route du salar."}}'::jsonb where slug = 'tupiza';
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Hotel with a view of Illimani", "description": "A double room in a quiet hotel in La Paz''s Zona Sur, with buffet breakfast and a clear view of Illimani. A few minutes from the cable car and the Valley of the Moon.\n\nReference photos: Kurt Kaiser (CC0); juhauski72 (CC BY 2.0), via Wikimedia Commons.", "duration_label": "Double room + breakfast", "includes": ["Buffet breakfast", "Wi-Fi", "Heating"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Hôtel avec vue sur l''Illimani", "description": "Chambre double dans un hôtel calme de la Zona Sur de La Paz, avec petit-déjeuner buffet et vue dégagée sur l''Illimani. À quelques minutes du téléphérique et de la Vallée de la Lune.\n\nPhotos de référence : Kurt Kaiser (CC0); juhauski72 (CC BY 2.0), via Wikimedia Commons.", "duration_label": "Chambre double + petit-déjeuner", "includes": ["Petit-déjeuner buffet", "Wi-Fi", "Chauffage"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-hotel-vista-illimani' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Modern apartment in Equipetrol", "description": "A bright two-bedroom apartment in Equipetrol, Santa Cruz''s restaurant and nightlife district. The building has a pool and parking.\n\nReference photos: Lo (CC0); EEJCC (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "2 bedrooms, up to 4 guests", "includes": ["Building pool", "Parking", "Fully equipped kitchen"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Appartement moderne à Equipetrol", "description": "Appartement lumineux de deux chambres à Equipetrol, le quartier des restaurants et de la vie nocturne de Santa Cruz. Immeuble avec piscine et parking.\n\nPhotos de référence : Lo (CC0); EEJCC (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "2 chambres, jusqu''à 4 personnes", "includes": ["Piscine de l''immeuble", "Parking", "Cuisine équipée"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-departamento-equipetrol' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "House with a pool in Samaipata", "description": "A country house for groups and families 10 minutes from Samaipata village, with a pool, garden and barbecue. Ideal for visiting El Fuerte and Amboró National Park.\n\nReference photos: Rospompom (CC BY-SA 3.0); Rospompom (CC BY-SA 3.0), via Wikimedia Commons.", "duration_label": "Entire house, up to 8 guests", "includes": ["Private pool", "Barbecue", "Garden"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Maison avec piscine à Samaipata", "description": "Maison de campagne pour groupes et familles à 10 minutes du village de Samaipata, avec piscine, jardin et barbecue. Idéale pour visiter El Fuerte et le parc national Amboró.\n\nPhotos de référence : Rospompom (CC BY-SA 3.0); Rospompom (CC BY-SA 3.0), via Wikimedia Commons.", "duration_label": "Maison entière, jusqu''à 8 personnes", "includes": ["Piscine privée", "Barbecue", "Jardin"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-casa-piscina-samaipata' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Hostel in Sucre''s historic center", "description": "A simple, clean hostel two blocks from Plaza 25 de Mayo. Private and shared rooms, breakfast included and a terrace overlooking the rooftops of the White City.\n\nReference photos: Ciacho5 (CC BY-SA 4.0); Parallelepiped09 (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Private room + breakfast", "includes": ["Breakfast", "Wi-Fi", "Shared terrace"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Auberge dans le centre historique de Sucre", "description": "Auberge simple et propre à deux rues de la place 25 de Mayo. Chambres privées et partagées, petit-déjeuner inclus et terrasse avec vue sur les toits de la Ville blanche.\n\nPhotos de référence : Ciacho5 (CC BY-SA 4.0); Parallelepiped09 (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Chambre privée + petit-déjeuner", "includes": ["Petit-déjeuner", "Wi-Fi", "Terrasse commune"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-hostal-centro-sucre' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Jungle ecolodge in Rurrenabaque", "description": "A 3-day program at a riverside ecolodge surrounded by the Amazon rainforest. Includes boat transfers, all meals and guided walks to spot monkeys, birds and caimans.\n\nReference photos: James Martins (CC BY 3.0); Gabrarq77 (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "3 days / 2 nights, all inclusive", "includes": ["Boat transfer", "All meals", "Naturalist guide"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Écolodge dans la jungle de Rurrenabaque", "description": "Programme de 3 jours dans un écolodge au bord du fleuve, en pleine forêt amazonienne. Transferts en bateau, tous les repas et randonnées guidées pour observer singes, oiseaux et caïmans.\n\nPhotos de référence : James Martins (CC BY 3.0); Gabrarq77 (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "3 jours / 2 nuits, tout compris", "includes": ["Transfert en bateau", "Tous les repas", "Guide naturaliste"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-ecolodge-rurrenabaque' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Cabins among the clouds in Coroico", "description": "Wooden cabins with a private terrace overlooking the Yungas, a pool and a barbecue area. Warm weather all year round, three hours from La Paz.\n\nReference photos: Forest Service Northern Region from Missoula, MT, USA (Public domain); Alhen (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Cabin for 4 guests", "includes": ["Private terrace", "Pool", "Barbecue"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Cabanes dans les nuages à Coroico", "description": "Cabanes en bois avec terrasse privée face aux Yungas, piscine et coin barbecue. Climat chaud toute l''année, à trois heures de La Paz.\n\nPhotos de référence : Forest Service Northern Region from Missoula, MT, USA (Public domain); Alhen (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Cabane pour 4 personnes", "includes": ["Terrasse privée", "Piscine", "Barbecue"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-cabanas-coroico' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Colonial boutique hotel in Sucre", "description": "A restored colonial mansion with an inner courtyard, only twelve rooms and its own restaurant. Steps from La Recoleta and the historic center.\n\nReference photos: alku (CC BY 3.0); Parallelepiped09 (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Superior room + breakfast", "includes": ["À la carte breakfast", "Wi-Fi", "Restaurant"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Hôtel boutique colonial à Sucre", "description": "Demeure coloniale restaurée avec patio intérieur, seulement douze chambres et son propre restaurant. À deux pas de La Recoleta et du centre historique.\n\nPhotos de référence : alku (CC BY 3.0); Parallelepiped09 (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Chambre supérieure + petit-déjeuner", "includes": ["Petit-déjeuner à la carte", "Wi-Fi", "Restaurant"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-hotel-boutique-sucre' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Glamping on the edge of the Uyuni Salt Flat", "description": "One night in a heated dome on the edge of the salt flat, with dinner, breakfast and a sunset tour on the mirror of water. For the clearest starry sky in Bolivia.\n\nReference photos: DONANENTHUSIAST (CC BY-SA 4.0); Diego Delso (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "1 night + sunset tour", "includes": ["Dinner and breakfast", "Sunset tour", "Heated dome"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Glamping face au salar d''Uyuni", "description": "Une nuit dans un dôme chauffé au bord du salar, avec dîner, petit-déjeuner et excursion au coucher du soleil sur le miroir d''eau. Pour le ciel étoilé le plus pur de Bolivie.\n\nPhotos de référence : DONANENTHUSIAST (CC BY-SA 4.0); Diego Delso (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "1 nuit + excursion au coucher du soleil", "includes": ["Dîner et petit-déjeuner", "Excursion au coucher du soleil", "Dôme chauffé"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-glamping-salar-uyuni' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Getaway to Isla del Sol", "description": "Two days on Lake Titicaca: a boat from Copacabana, a hike along the Inca trails of Isla del Sol and a night at a guesthouse overlooking the lake.\n\nReference photos: Jawira (CC BY-SA 4.0); Qhanaaru (CC0), via Wikimedia Commons.", "duration_label": "2 days / 1 night", "includes": ["Round-trip boat", "Accommodation", "Breakfast", "Local guide"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Escapade sur l''Isla del Sol", "description": "Deux jours sur le lac Titicaca : bateau depuis Copacabana, randonnée sur les sentiers incas de l''Isla del Sol et nuit dans une auberge avec vue sur le lac.\n\nPhotos de référence : Jawira (CC BY-SA 4.0); Qhanaaru (CC0), via Wikimedia Commons.", "duration_label": "2 jours / 1 nuit", "includes": ["Bateau aller-retour", "Hébergement", "Petit-déjeuner", "Guide local"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-escapada-isla-del-sol' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Wine and singani route in Tarija", "description": "Three days through the high-altitude vineyards of the Central Valley: winery visits, wine and singani tastings, a country lunch and accommodation in downtown Tarija.\n\nReference photos: Aldrihe (CC BY-SA 4.0); Aldrihe (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "3 days / 2 nights", "includes": ["Accommodation", "Visits to 3 wineries", "Tastings", "Transport"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Route du vin et du singani à Tarija", "description": "Trois jours dans les vignobles d''altitude de la Vallée centrale : visites de caves, dégustations de vin et de singani, déjeuner champêtre et hébergement au centre de Tarija.\n\nPhotos de référence : Aldrihe (CC BY-SA 4.0); Aldrihe (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "3 jours / 2 nuits", "includes": ["Hébergement", "Visite de 3 caves", "Dégustations", "Transport"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-ruta-del-vino-tarija' and is_sample;
update public.products set translations = coalesce(translations, '{}'::jsonb) || '{"en": {"title": "Expedition to the Torotoro Canyon", "description": "A full day in Torotoro National Park: the canyon viewpoint, the descent to El Vergel, dinosaur footprints and the Umajalanta Cave with a community guide.\n\nReference photos: Gaumut (CC BY-SA 3.0); Vaido Otsar (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "1 day", "includes": ["Community guide", "Park entrance", "Lunch"], "booking_conditions": "Sample deal: it can''t be booked.", "cancellation_policy": "Sample deal."}, "fr": {"title": "Expédition au canyon de Torotoro", "description": "Une journée complète dans le parc national de Torotoro : belvédère du canyon, descente à El Vergel, empreintes de dinosaures et grotte d''Umajalanta avec un guide communautaire.\n\nPhotos de référence : Gaumut (CC BY-SA 3.0); Vaido Otsar (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "1 jour", "includes": ["Guide communautaire", "Entrée du parc", "Déjeuner"], "booking_conditions": "Offre d''exemple : elle ne peut pas être réservée.", "cancellation_policy": "Offre d''exemple."}}'::jsonb where slug = 'ejemplo-expedicion-canon-torotoro' and is_sample;
